import{_ as e,o,c as a,a3 as n}from"./chunks/framework.BveOjhN0.js";const p=JSON.parse('{"title":"Contacts — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contacts — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/contacts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contacts — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/contacts"}]]},"headers":[],"relativePath":"deployment/contacts.md","filePath":"deployment/contacts.md","lastUpdated":1785703811000}'),i={name:"deployment/contacts.md"};function c(s,t,r,l,d,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="contacts-—-production-guide" tabindex="-1">Contacts — Production Guide <a class="header-anchor" href="#contacts-—-production-guide" aria-label="Permalink to &quot;Contacts — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>contacts</code></li><li><strong>Free Marketplace opt-in</strong> CRM module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code></li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Contacts from Marketplace</li><li>Existing workspaces that already have Contacts keep their subscription</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable Contacts from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>contacts.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage or status seeder (unlike Leads) — Contacts is a flat directory record.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Contacts permissions for <strong>existing</strong> workspaces must ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>contact_created</code>, <code>contact_updated</code>, <code>contact_deleted</code>, <code>contact_assigned</code>, <code>contact_note_added</code>, <code>contact_restored</code></li><li>Notifications: assignment (mail + database) via <code>ContactAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="lead-integration" tabindex="-1">Lead integration <a class="header-anchor" href="#lead-integration" aria-label="Permalink to &quot;Lead integration&quot;">​</a></h2><p>When Contacts is installed alongside Leads, <code>leads.convert</code> starts creating/linking real Contacts (<code>leads.contact_id</code>) instead of the status-only placeholder. No backfill runs automatically for leads converted before Contacts was installed — those keep <code>conversion_meta.stub = true</code>.</p><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate contact tables (<code>contacts</code>, <code>contact_notes</code>, <code>contact_activities</code>) and <code>leads.contact_id</code></li><li>Register the <code>contacts</code> catalog module (migration, not seeder)</li><li>Confirm <code>module:contacts</code> + <code>contacts.*</code> permissions on target roles</li><li>Deploy frontend (Contacts nav item, list/form/detail, dashboard <strong>Recent Contacts</strong> widget + <strong>Create Contact</strong> quick action, Lead detail <strong>View contact</strong> link)</li><li>Smoke: create a <strong>new</strong> workspace → enable Contacts from Marketplace → create/edit/assign/note a contact → convert a Lead → confirm <code>contact_id</code> + <strong>View contact</strong> link</li></ol>',15)])])}const u=e(i,[["render",c]]);export{p as __pageData,u as default};
